BEGIN READ ONLY;
SELECT current_user,session_user,current_setting('server_version');
SELECT rolname,rolsuper,rolcreaterole,rolcanlogin FROM pg_roles WHERE rolname IN ('postgres','supabase_admin','academy_retention_definer');
SELECT pg_has_role('postgres','academy_retention_definer','MEMBER'),has_schema_privilege('academy_retention_definer','academy','CREATE');
SELECT proname,pg_get_userbyid(proowner) FROM pg_proc WHERE pronamespace='academy'::regnamespace AND proname LIKE 'run_retention_%' ORDER BY proname;
COMMIT;
